// Impact of Vaccines — Heatmap, route: jsx
// Source: the-impact-of-vaccines
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from vaccines ----
/**
 * Synthetic incidence stand-in shaped like a pre/post-vaccination surveillance record.
 * Invented regions and an invented illness — no real disease, place or agency is described.
 */

const START_YEAR = 1928;
const END_YEAR = 1997;
const VACCINE_YEAR = 1963;

const regions = [
  'Ardel', 'Bexley', 'Calder', 'Dorne', 'Elmar', 'Fenwick', 'Garnet', 'Hallow', 'Ivrin',
  'Jarrow', 'Kelvin', 'Larkin', 'Marden', 'Norwell', 'Ostend', 'Pelham', 'Quarry', 'Redvale',
  'Selby', 'Thorne', 'Ulvern', 'Vandry', 'Westra', 'Xander', 'Yarrow', 'Zephon', 'Aldon',
  'Brennig', 'Corvale', 'Dunmor', 'Eastby', 'Fallow', 'Glenby', 'Harrow', 'Inglet', 'Jessup',
  'Kirkby', 'Lowden', 'Marshby', 'Newlyn', 'Orwell', 'Preswik', 'Quinby', 'Rothley', 'Stanmor',
  'Tarrow', 'Upton', 'Vellan', 'Wexford', 'Yardly'
];

const years = Array.from(
  { length: END_YEAR - START_YEAR + 1 },
  (_, i) => START_YEAR + i
);

// Seeded PRNG so the corpus is byte identical on every render, reload and machine.
function mulberry32(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** null marks a region-year with no report; the chart renders those as a neutral cell. */
function buildIncidence(): (number | null)[][] {
  const random = mulberry32(19630311);
  const preVaccineSpan = VACCINE_YEAR - START_YEAR;

  return regions.map(() => {
    const base = 90 + 520 * random();
    const cycleLength = 2 + Math.round(2 * random());
    const phase = 6 * random();
    const reportingStart = START_YEAR + Math.floor(9 * random());

    return years.map((year) => {
      if (year < reportingStart) return null;
      const elapsed = year - VACCINE_YEAR;
      const cycle = 0.3 + 0.9 * Math.sin((Math.PI * (year - phase)) / cycleLength) ** 2;
      const drift = 1 - 0.3 * Math.min(1, (year - START_YEAR) / preVaccineSpan);
      const collapse = elapsed <= 0 ? 1 : Math.exp(-elapsed / 2.6);
      // Sporadic post-programme flare-ups, so the tail is scattered rather than uniformly empty.
      const flare = elapsed > 0 && random() < 0.06 ? 2 + 12 * random() : 0;
      const value = base * cycle * drift * collapse * (0.8 + 0.4 * random()) + flare;
      return value < 0.4 ? 0 : Math.round(value * 10) / 10;
    });
  });
}

const incidence = buildIncidence();

const MARGIN = { top: 64, right: 12, bottom: 54, left: 66 };
const THRESHOLDS = [1, 10, 25, 50, 100, 200, 350, 550];
const LEGEND = { width: 320, y: 18, height: 12 };

// Dark-first ramp: low values sit near the page background, high values burn bright.
const BINS = d3.range(9).map((i) => d3.interpolateMagma(0.18 + (0.75 * i) / 8));
const NO_REPORT = '#3a3e42';
const ZERO = '#1b1e20';

/** Below this row height the region labels collide, so every other one is dropped. */
const MIN_LABEL_HEIGHT = 11.5;
const MIN_SWATCH_WIDTH = 480;

const formatCount = d3.format(',.0f');
const formatYear = d3.format('d');

/** A region-by-year value matrix (null where nothing was reported), its row and column keys, and the event year the rule marks. */
export type Data = {
  regions: string[];
  years: number[];
  incidence: (number | null)[][];
  startYear: number;
  endYear: number;
  eventYear: number;
};

const DEMO: Data = {
  regions,
  years,
  incidence,
  startYear: START_YEAR,
  endYear: END_YEAR,
  eventYear: VACCINE_YEAR
};

function describe(value: number | null) {
  if (value === null) return 'no report';
  if (value === 0) return '0 cases';
  if (value < 1.5) return '1 case';
  return `${formatCount(value)} cases`;
}

export default function ImpactOfVaccines({ data = DEMO, width }:
  { data?: Data; width: number }) {
  const rowHeight = Math.max(7, Math.min(15, width / 68));
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = Math.round(rowHeight * data.regions.length);
  const height = innerHeight + MARGIN.top + MARGIN.bottom;

  const x = useMemo(
    () => d3.scaleLinear().domain([data.startYear, data.endYear + 1]).range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () => d3.scaleBand<string>().domain(data.regions).range([0, innerHeight]),
    [data, innerHeight]
  );

  const color = useMemo(
    () => d3.scaleThreshold<number, string>().domain(THRESHOLDS).range(BINS),
    []
  );

  const cellWidth = Math.max(1, innerWidth / data.years.length - 1);

  const rows = useMemo(
    () =>
      data.regions.map((name, i) => ({
        name,
        top: y(name) ?? 0,
        cells: data.incidence[i].map((value, j) => ({
          year: data.years[j],
          x: x(data.years[j]) + 0.5,
          fill: value === null ? NO_REPORT : value === 0 ? ZERO : color(value),
          title: `${name} ${data.years[j]}: ${describe(value)} per 100,000`
        }))
      })),
    [data, x, y, color]
  );

  const yTicks: Tick[] = useMemo(() => {
    const step = rowHeight >= MIN_LABEL_HEIGHT ? 1 : 2;
    return data.regions
      .filter((_, i) => i % step === 0)
      .map((name) => ({ value: name, offset: (y(name) ?? 0) + y.bandwidth() / 2 }));
  }, [data, y, rowHeight]);

  const xTicks: Tick[] = useMemo(
    () =>
      x
        .ticks(Math.max(3, Math.round(innerWidth / 90)))
        .filter((v) => v >= data.startYear && v <= data.endYear)
        .map((v) => ({ value: formatYear(v), offset: x(v) })),
    [data, x, innerWidth]
  );

  const legendWidth = Math.min(LEGEND.width, innerWidth);
  const blockWidth = legendWidth / BINS.length;
  const legendTicks: Tick[] = useMemo(
    () =>
      THRESHOLDS.map((v, i) => ({ value: formatCount(v), offset: (i + 1) * blockWidth })).filter(
        (t) => t.value.length * 6.4 + 4 <= blockWidth * 2
      ),
    [blockWidth]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={
        `Heatmap of synthetic illness incidence per 100,000 people across 50 invented regions, ` +
        `${data.startYear} to ${data.endYear}, one cell per region and year. Incidence runs high and ` +
        `cyclical until the marked ${data.eventYear} vaccination programme, then collapses to near ` +
        `zero within a decade. Synthetic data from a seeded generator, not a real disease ` +
        `surveillance record.`
      }
    >
      <g transform={`translate(${MARGIN.left},${LEGEND.y})`}>
        <text y={-6} fill="var(--text)" fontSize={12} fontWeight={600}>
          Cases per 100,000 people
        </text>
        {BINS.map((fill, i) => (
          <rect key={fill} x={i * blockWidth} width={blockWidth} height={LEGEND.height} fill={fill} />
        ))}
        <g className="axis" transform={`translate(0,${LEGEND.height})`}>
          {legendTicks.map(({ value, offset }) => (
            <g key={value} transform={`translate(${offset},0)`}>
              <line y1={0} y2={4} />
              <text y={16} textAnchor="middle">
                {value}
              </text>
            </g>
          ))}
        </g>
        {innerWidth >= MIN_SWATCH_WIDTH && (
          <g transform={`translate(${legendWidth + 24},0)`}>
            <rect width={LEGEND.height} height={LEGEND.height} fill={ZERO} stroke="var(--line)" />
            <text x={LEGEND.height + 6} y={10} fill="var(--muted)" fontSize={11}>
              none
            </text>
            <rect x={64} width={LEGEND.height} height={LEGEND.height} fill={NO_REPORT} />
            <text x={64 + LEGEND.height + 6} y={10} fill="var(--muted)" fontSize={11}>
              no report
            </text>
          </g>
        )}
      </g>

      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        {rows.map((row) => (
          <g key={row.name} transform={`translate(0,${row.top})`}>
            {row.cells.map((cell) => (
              <rect
                key={cell.year}
                x={cell.x}
                width={cellWidth}
                height={Math.max(1, y.bandwidth() - 1)}
                fill={cell.fill}
              >
                <title>{cell.title}</title>
              </rect>
            ))}
          </g>
        ))}
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />

        <line
          x1={x(data.eventYear)}
          x2={x(data.eventYear)}
          y1={-6}
          y2={innerHeight + 6}
          stroke="var(--text)"
          strokeWidth={1.5}
        />
        <text
          x={x(data.eventYear)}
          y={innerHeight + 38}
          textAnchor="middle"
          fill="var(--text)"
          fontSize={11}
          fontWeight={700}
        >
          Vaccination programme begins
        </text>
      </g>

      {/* A collapse curve that looks like epidemiology is the one output here that could mislead. */}
      <text x={MARGIN.left} y={height - 4} fill="var(--muted)" fontSize={10}>
        Synthetic data from a seeded generator, not a real disease surveillance record.
      </text>
    </svg>
  );
}
